"""SQLAlchemy ORM models: the database schema that Alembic migrations follow."""

from datetime import datetime

from sqlalchemy import BigInteger, CheckConstraint, DateTime, ForeignKey, MetaData, Text, func
from sqlalchemy.orm import DeclarativeBase, Mapped, mapped_column

# Deterministic constraint names, so autogenerated migrations can drop and alter
# constraints by name instead of relying on names Postgres invents.
NAMING_CONVENTION = {
    "ix": "ix_%(column_0_label)s",
    "uq": "uq_%(table_name)s_%(column_0_name)s",
    "ck": "ck_%(table_name)s_%(constraint_name)s",
    "fk": "fk_%(table_name)s_%(column_0_name)s_%(referred_table_name)s",
    "pk": "pk_%(table_name)s",
}


class Base(DeclarativeBase):
    """Base class for all ORM models; its metadata is the target for Alembic."""

    metadata = MetaData(naming_convention=NAMING_CONVENTION)


class User(Base):
    """A Telegram user who joined the bot.

    ``invited_by`` has no ``relationship()`` on purpose: lazy loads do not work under
    asyncio, so repositories load the inviter explicitly when they need it.
    """

    __tablename__ = "users"
    __table_args__ = (
        # Text plus CHECK instead of a native ENUM: adding a role later is a one-line
        # constraint change rather than an ALTER TYPE migration.
        CheckConstraint("role IN ('admin', 'user', 'blocked')", name="role_valid"),
        CheckConstraint("tg_id > 0", name="tg_id_positive"),
        CheckConstraint("invited_by <> tg_id", name="not_self_invited"),
    )

    # Telegram user IDs are natural keys and exceed 32 bits, hence BIGINT without a sequence.
    tg_id: Mapped[int] = mapped_column(BigInteger, primary_key=True, autoincrement=False)
    # Stored without the leading "@"; not unique because users can rename and reuse names.
    username: Mapped[str | None] = mapped_column(Text)
    role: Mapped[str] = mapped_column(Text, server_default="user")
    invited_by: Mapped[int | None] = mapped_column(
        BigInteger, ForeignKey("users.tg_id", ondelete="SET NULL")
    )
    created_at: Mapped[datetime] = mapped_column(DateTime(timezone=True), server_default=func.now())
